<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { RefreshCw } from 'lucide-vue-next'
import { errorText } from '../api'
import { settlement, number, type FAQ, type Gap } from '../settlement'
import { useAuth } from '../stores/auth'
import { useUnsaved } from '../useUnsaved'
import PageHeader from '../components/PageHeader.vue'
import AsyncState from '../components/AsyncState.vue'
import FieldInput from '../components/FieldInput.vue'
import FormDialog from '../components/FormDialog.vue'
import ChatMarkdown from '../components/ChatMarkdown.vue'
import '../settlement.css'
const auth=useAuth(),route=useRoute(),router=useRouter()
const isGap=computed(()=>route.query.tab==='gaps'),status=ref('pending_review'),page=ref(1),total=ref(0)
const faqs=ref<FAQ[]>([]),gaps=ref<Gap[]>([]),loading=ref(true),error=ref(''),busy=ref(false),mining=ref(false),notice=ref('')
const selected=ref<FAQ|null>(null),answer=ref(''),formError=ref(''),resolveGap=ref<Gap|null>(null),requestId=ref('')
let alive=true,revision=0,timer:ReturnType<typeof setInterval>|undefined
const canRead=computed(()=>isGap.value?auth.has('settlement:gap:manage'):auth.has('settlement:faq:read'))
useUnsaved(()=>!!selected.value&&answer.value!==(selected.value.answer||''),()=>busy.value)
async function load(quiet=false){if(!canRead.value){faqs.value=[];gaps.value=[];loading.value=false;error.value='当前角色没有此列表的读取权限。';return}const rev=++revision;if(!quiet)loading.value=true;error.value='';try{if(isGap.value){const value=await settlement.gaps(status.value,page.value);if(!alive||rev!==revision)return;gaps.value=value.items;total.value=value.total}else{const value=await settlement.faqs(status.value,page.value);if(!alive||rev!==revision)return;faqs.value=value.items;total.value=value.total;if(selected.value&&!value.items.some(f=>f.id===selected.value?.id&&f.source_valid)){selected.value=null;answer.value=''}}}catch(e){if(alive&&rev===revision){error.value=errorText(e);faqs.value=[];gaps.value=[];selected.value=null;answer.value=''}}finally{if(alive&&rev===revision)loading.value=false}}
async function mine(){mining.value=true;notice.value='';try{const result=await settlement.mine();notice.value=`新增 ${result.created_faqs} 条 FAQ 推荐、${result.created_gaps} 条知识缺口。${result.mode==='exact_fallback'?'语义服务暂不可用，本次按相同问题聚合。':''}${result.truncated?'日志超过单次上限，本次处理最近窗口。':''}`;await load()}catch(e){notice.value=errorText(e)}finally{mining.value=false}}
function open(row:FAQ){selected.value=row;answer.value=row.answer||'';formError.value=''}
async function close(){if(selected.value&&answer.value!==(selected.value.answer||'')){try{await ElMessageBox.confirm('离开将丢弃尚未保存的答案。','保留修改',{confirmButtonText:'丢弃修改',cancelButtonText:'继续编辑'})}catch{return}}selected.value=null;answer.value=''}
async function save(){if(!selected.value||busy.value)return;busy.value=true;formError.value='';try{if(selected.value.status==='pending_review')await settlement.review(selected.value,'approve',answer.value);else await settlement.edit(selected.value,answer.value);selected.value=null;answer.value='';ElMessage.success('已保存审核结果');await load()}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
async function action(row:FAQ,kind:'reject'|'withdraw'){try{await ElMessageBox.confirm(kind==='reject'?'驳回后不会发布这条建议答案。':'撤回后，此 FAQ 将不再用于回答。',kind==='reject'?'驳回 FAQ':'撤回 FAQ',{confirmButtonText:kind==='reject'?'确认驳回':'确认撤回',cancelButtonText:'取消'})}catch{return}busy.value=true;try{if(kind==='reject')await settlement.review(row,'reject');else await settlement.withdraw(row);await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function gapState(row:Gap,next:string){busy.value=true;try{await settlement.state(row,next);await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function resolve(){if(!resolveGap.value)return;busy.value=true;formError.value='';try{await settlement.state(resolveGap.value,'resolved',requestId.value);resolveGap.value=null;await load()}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
function switchTab(tab:string){void router.push({path:'/settlement',query:{tab}})}
watch(()=>route.query.tab,()=>{status.value=isGap.value?(route.query.status==='resolved'?'resolved':'unresolved'):route.query.tab==='published'?'published':'pending_review';page.value=1;selected.value=null;answer.value='';void load()})
watch(()=>auth.permissions.join('|'),()=>void load(true))
onMounted(()=>{status.value=isGap.value?(route.query.status==='resolved'?'resolved':'unresolved'):route.query.tab==='published'?'published':'pending_review';void load();timer=setInterval(()=>{if(document.visibilityState==='visible'&&!busy.value)void load(true)},30000)})
onUnmounted(()=>{alive=false;revision++;clearInterval(timer)})
</script>
<template><div class="settlement-screen">
<PageHeader title="知识沉淀" description="把重复提问变成标准答案，把未解问题补成知识。"><button v-if="auth.has('settlement:faq:review')&&auth.has('settlement:gap:manage')" class="button primary" :disabled="mining||busy" @click="mine">{{mining?'正在分析问题…':'挖掘最新问题'}}</button></PageHeader>
<nav class="tabs" aria-label="知识沉淀分类"><button :class="{active:!isGap&&route.query.tab!=='published'}" @click="switchTab('recommendations')">FAQ 推荐审核</button><button :class="{active:route.query.tab==='published'}" @click="switchTab('published')">已发布 FAQ</button><button :class="{active:isGap}" @click="switchTab('gaps')">知识缺口</button></nav>
<p v-if="notice" class="settlement-notice" role="status">{{notice}}</p>
<div class="settlement-toolbar"><label for="settlement-status">状态</label><select id="settlement-status" aria-label="状态" v-model="status" @change="page=1;load()"><template v-if="isGap"><option value="unresolved">未解决</option><option value="resolved">已解决</option><option value="ignored">已忽略</option></template><template v-else><option value="pending_review">待审核</option><option value="published">已发布</option><option value="rejected">已驳回</option><option value="withdrawn">已撤回</option></template></select><span class="muted">共 <b class="num">{{number(total)}}</b> 条{{isGap?'知识缺口':'可管理 FAQ'}}</span><button class="button" :disabled="loading" @click="load()"><RefreshCw :size="15"/>刷新</button></div>
<AsyncState :loading="loading" :error="error" :empty="!total" :empty-text="isGap?'当前没有此状态的知识缺口':'当前没有此状态的 FAQ'" @retry="load()"><template #empty><p>新问题会从实际问答记录中聚合，运行挖掘后可刷新查看。</p></template>
<div v-if="!isGap" class="settlement-list"><article v-for="row in faqs" :key="row.id" class="settlement-row"><div class="settlement-object"><h2>{{row.question}}</h2><p>{{row.source_valid?`依赖 ${row.sources.length} 个来源切片，回答前逐一核对访问权。`:'来源版本或授权已变化，缓存不会返回此答案。'}}</p><ChatMarkdown v-if="row.answer" :content="row.answer" class="faq-preview"/><div v-if="row.source_valid" class="faq-sources"><RouterLink v-for="source in row.sources" :key="source.chunk_id" :to="`/knowledge/${source.unit_id}`">{{source.title||'知识来源'}}</RouterLink></div></div><div class="settlement-meta"><span>提问 <b class="num">{{number(row.frequency)}}</b> 次</span><span>缓存回答 <b class="num">{{number(row.hit_count)}}</b> 次</span><span>{{row.cache_state==='eligible'?'已发布 · 按当前访问权生效':'未启用缓存'}}</span></div><div class="settlement-actions"><button v-if="row.source_valid&&auth.has('settlement:faq:review')&&(row.status!=='published'||auth.has('settlement:faq:publish'))" class="button" :disabled="busy||(row.status==='pending_review'&&!auth.has('settlement:faq:publish'))" @click="open(row)">{{row.status==='pending_review'?'审核答案':'编辑并重新审核'}}</button><button v-if="row.status==='pending_review'&&row.source_valid&&auth.has('settlement:faq:review')" class="text-button" :disabled="busy" @click="action(row,'reject')">驳回</button><button v-if="row.status==='published'&&auth.has('settlement:faq:publish')" class="text-button" :disabled="busy" @click="action(row,'withdraw')">撤回发布</button></div></article></div>
<div v-else class="settlement-list"><article v-for="row in gaps" :key="row.id" class="settlement-row"><div class="settlement-object"><h2>{{row.question_pattern}}</h2><p>未命中或依据不足的提问；不包含纯权限受限问题。</p><p v-for="sample in row.sample_questions.filter(q=>q!==row.question_pattern).slice(0,2)" :key="sample">{{sample}}</p><RouterLink v-if="row.resolved_unit_id" :to="`/knowledge/${row.resolved_unit_id}`" class="text-button">查看补全知识</RouterLink></div><div class="settlement-meta"><span>提问 <b class="num">{{number(row.ask_count)}}</b> 次</span><time>{{row.last_asked_at?new Date(row.last_asked_at).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}):'时间未提供'}}</time></div><div class="settlement-actions"><RouterLink v-if="!row.resolved_unit_id&&auth.has('knowledge:create')" :to="{path:'/knowledge/new',query:{gap:row.id,title:row.question_pattern}}" class="button">创建知识草稿</RouterLink><RouterLink v-if="row.resolved_unit_id&&row.status==='unresolved'" :to="{path:'/chat',query:{question:row.question_pattern,gap:row.id}}" class="button">验证原问题</RouterLink><button v-if="row.resolved_unit_id&&row.status==='unresolved'" class="text-button" :disabled="busy" @click="resolveGap=row;requestId='';formError=''">确认补全结果</button><button v-if="row.status==='unresolved'" class="text-button" :disabled="busy" @click="gapState(row,'ignored')">忽略</button><button v-else class="text-button" :disabled="busy" @click="gapState(row,'unresolved')">重新打开</button></div></article></div>
<div v-if="total>20" class="settlement-paging"><button class="button" :disabled="page===1||loading" @click="page--;load()">上一页</button><span class="num">{{page}} / {{Math.ceil(total/20)}}</span><button class="button" :disabled="page*20>=total||loading" @click="page++;load()">下一页</button></div>
</AsyncState>
<FormDialog :open="!!selected" :title="selected?.status==='pending_review'?'审核并发布 FAQ':'编辑 FAQ'" :busy="busy" :error="formError" :submit-label="selected?.status==='pending_review'?'审核通过并发布':'保存为待审核'" @close="close" @submit="save"><p class="dialog-question">{{selected?.question}}</p><FieldInput v-slot="{id}" label="标准答案" required><textarea :id="id" v-model="answer" rows="9" required maxlength="50000"/></FieldInput><p class="muted">发布前核对全部来源。答案修改后需要重新审核。</p></FormDialog>
<FormDialog :open="!!resolveGap" title="确认补全结果" :busy="busy" :error="formError" submit-label="验证并标记已解决" @close="resolveGap=null" @submit="resolve"><p class="dialog-question">{{resolveGap?.question_pattern}}</p><FieldInput v-slot="{id}" label="成功问答的请求编号" required hint="验证原问题后，可在已完成的回答下复制编号。"><input :id="id" v-model="requestId" required/></FieldInput><p class="muted">系统会核对原问题、当前发布版本与实际引用；创建草稿本身不会关闭缺口。</p></FormDialog>
</div></template>
